(function(){
var stops=[
{name:'断桥残雪',day:1,lat:30.259,lng:120.151,stay:'40分钟',ticket:'免费',go:'地铁1号线龙翔桥/湖滨步行15分钟',pit:'十月人少但仍是自拍点，早8点最空。白堤单向人流，别逆行骑车。',why:'白娘子传说起点，秋水拍岸最出片。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/West_Lake_%E8%A5%BF%E6%B9%96_-_panoramio_%2810%29.jpg/330px-West_Lake_%E8%A5%BF%E6%B9%96_-_panoramio_%2810%29.jpg',credit:'lienyuan lee · CC BY 3.0',curl:'https://commons.wikimedia.org/wiki/File:West_Lake_%E8%A5%BF%E6%B9%96_-_panoramio_(10).jpg'},
{name:'西湖（白堤·平湖秋月）',day:1,lat:30.254,lng:120.144,stay:'2小时步行',ticket:'湖岸免费；游船约55–80',go:'沿白堤向西至孤山',pit:'平湖秋月十月名副其实。游船选手划船更静。',why:'秋季西湖核心体验：银杏将黄、桂香未尽。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/330px-West_Lake%2C_Hangzhou_2025.jpg',credit:'Takashishin · CC BY 4.0',curl:'https://commons.wikimedia.org/wiki/File:West_Lake,_Hangzhou_2025.jpg'},
{name:'雷峰塔',day:1,lat:30.231,lng:120.149,stay:'70分钟',ticket:'约40–50（含登塔）',go:'南山路公交或打车15分钟',pit:'电梯+步梯。夕阳从四层西望最美，闭馆前1小时人少。',why:'白蛇镇塔传说；登顶看南湖与苏堤几何线。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Leifeng_Pagoda_DJI_0593_%282%29.jpg/330px-Leifeng_Pagoda_DJI_0593_%282%29.jpg',credit:'David290 · CC BY-SA 4.0',curl:'https://commons.wikimedia.org/wiki/File:Leifeng_Pagoda_DJI_0593_(2).jpg'},
{name:'河坊街·吴山夜市',day:1,lat:30.243,lng:120.169,stay:'1.5小时',ticket:'免费',go:'雷峰塔打车10分钟或公交',pit:'小吃卫生看翻台率。定胜糕、小笼、藕粉可作晚饭。',why:'南宋御街余韵，单人晚餐不必正餐厅。',photo:'https://commons.wikimedia.org/wiki/Special:FilePath/West_Lake_-_Hangzhou.jpg?width=480',credit:'Baycrest · CC BY-SA 2.5',curl:'https://commons.wikimedia.org/wiki/File:West_Lake_-_Hangzhou.jpg'},
{name:'灵隐寺·飞来峰',day:2,lat:30.241,lng:120.101,stay:'2.5小时',ticket:'飞来峰45+灵隐约30，合计约75',go:'地铁3号线花坞/洪春桥转Y2或打车',pit:'先飞来峰看造像再进寺。素面约25–40。勿信门口拉客。',why:'江南禅寺标杆，秋日香樟与石窟最静。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Lingyin_Temple%2C_Hangzhou_20161003.jpg/330px-Lingyin_Temple%2C_Hangzhou_20161003.jpg',credit:'Tyg728 · CC BY-SA 4.0',curl:'https://commons.wikimedia.org/wiki/File:Lingyin_Temple,_Hangzhou_20161003.jpg'},
{name:'龙井村·狮峰',day:2,lat:30.22,lng:120.12,stay:'2小时',ticket:'村口免费；茶馆茶位50–120',go:'灵隐打车15分钟或公交324',pit:'十月非春茶季，买明前龙井要认准包装与产地。可徒步九溪。',why:'喝一盏狮峰龙井，看梯田秋色。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Longjing_tea.jpg/330px-Longjing_tea.jpg',credit:'Difference engine · CC BY-SA 4.0',curl:'https://commons.wikimedia.org/wiki/File:Longjing_tea.jpg'},
{name:'西溪国家湿地公园',day:3,lat:30.272,lng:120.063,stay:'3小时',ticket:'周家村80左右，含摇橹船更值',go:'地铁3号线洪园/沿山河',pit:'走绿堤+烟水渔庄一线即可，别贪全园。秋芦花是重点。',why:'城市里的湿地，单人最适合慢走发呆。',photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Xixi_Wetland_Park%2C_Hangzhou%2C_China.jpg/330px-Xixi_Wetland_Park%2C_Hangzhou%2C_China.jpg',credit:'Yoshi Canopus · CC BY-SA 3.0',curl:'https://commons.wikimedia.org/wiki/File:Xixi_Wetland_Park,_Hangzhou,_China.jpg'},
{name:'京杭大运河（拱宸桥）',day:3,lat:30.319,lng:120.14,stay:'1.5小时',ticket:'桥与河岸免费；博物馆约0–20',go:'地铁5号线拱宸桥东',pit:'傍晚灯带亮起拍照。单人晚饭可选运河边面馆。',why:'世界遗产河段，补齐杭州「湖+河」双名片。',photo:'https://commons.wikimedia.org/wiki/Special:FilePath/West_Lake_-_Hangzhou.jpg?width=480',credit:'Baycrest · CC BY-SA 2.5',curl:'https://commons.wikimedia.org/wiki/File:West_Lake_-_Hangzhou.jpg'}
];
var strip=document.getElementById('strip');
var sheet=document.getElementById('sheet');
var tl=document.getElementById('tl');
function fillSheet(s,i){
sheet.className='sheet on';
sheet.innerHTML='<h4>'+(i+1)+'. '+s.name+'</h4><p>'+s.why+'</p><p><b>停留</b> '+s.stay+' · <b>票或预约</b> '+s.ticket+'</p><p><b>怎么去</b> '+s.go+'</p><p><b>避坑</b> '+s.pit+'</p>';
}
stops.forEach(function(s,i){
var c=document.createElement('div');
c.className='iui-stop-card';
c.setAttribute('data-iui-place',s.name);
c.innerHTML='<div class="photo"><img src="'+s.photo+'" alt="'+s.name+'" loading="eager"></div><div class="num">'+(i+1)+'</div><div class="name">'+s.name+'</div><div class="muted">D'+s.day+' · '+s.stay+'</div><div class="iui-photo-credit"><a href="'+s.curl+'">'+s.credit+'</a></div>';
c.onclick=function(){fillSheet(s,i);if(window.__trip)window.__trip.seek(i);};
strip.appendChild(c);
});
var days={
1:'<p><b>08:20</b> 断桥→白堤散步（免费）</p><p><b>10:30</b> 孤山 / 平湖秋月 / 楼外楼早茶或知味观点心 ¥40–90</p><p><b>14:00</b> 苏堤南段→雷峰塔登塔 ¥40–50</p><p><b>17:30</b> 南山路日落，河坊街小吃晚饭 ¥50–80</p><p><b>住</b> 湖滨步行范围内，方便夜逛湖</p>',
2:'<p><b>08:30</b> 灵隐飞来峰+寺院 ¥75，素面午餐</p><p><b>13:00</b> 龙井村茶馆一盏 ¥50–120</p><p><b>16:00</b> 可选九溪烟树下行，回湖滨</p><p><b>晚</b> 湖滨银泰或外婆家 ¥60–100</p>',
3:'<p><b>09:00</b> 西溪周家村入口，绿堤+摇橹 ¥80+</p><p><b>13:30</b> 园内或文二路简餐</p><p><b>16:00</b> 地铁去拱宸桥，运河夜色</p><p><b>离杭</b> 东站/西站预留 60–90 分钟</p>'
};
function showDay(d){tl.innerHTML=days[d];}
showDay(1);
document.getElementById('d1').onclick=function(){showDay(1);if(window.__trip)window.__trip.seek(0);};
document.getElementById('d2').onclick=function(){showDay(2);if(window.__trip)window.__trip.seek(4);};
document.getElementById('d3').onclick=function(){showDay(3);if(window.__trip)window.__trip.seek(6);};
var map=L.map('map',{scrollWheelZoom:false}).setView([30.25,120.13],12);
L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri',maxZoom:19}).addTo(map);
var latlngs=[];var pinElements=[];
stops.forEach(function(s,i){
var icon=L.divIcon({className:'',html:'<div class="iui-pin-dot">'+(i+1)+'</div>',iconSize:[24,24]});
var m=L.marker([s.lat,s.lng],{icon:icon}).addTo(map);
m.on('click',function(){fillSheet(s,i);});
latlngs.push([s.lat,s.lng]);
var el=m.getElement();if(el)pinElements.push(el);
});
L.polyline(latlngs,{color:'#5b8def',weight:3,opacity:.7}).addTo(map).bindTooltip('示意行程连线 — 非核实驾车路线');
setTimeout(function(){map.invalidateSize();},200);
if(window.createTripAnimator){
window.__trip=createTripAnimator({stopCount:stops.length,durationMs:8000,pinElements:pinElements,map:map,onFrame:function(i){
var cards=strip.querySelectorAll('.iui-stop-card');
cards.forEach(function(c,idx){c.setAttribute('aria-current',idx===i?'true':'false');});
if(cards[i])strip.scrollLeft=cards[i].offsetLeft-12;
fillSheet(stops[i],i);
document.getElementById('st').textContent='当前：D'+stops[i].day+' · '+stops[i].name;
},onState:function(){}});
}
document.getElementById('pause').onclick=function(){if(window.__trip)window.__trip.pause();};
document.getElementById('replay').onclick=function(){if(window.__trip)window.__trip.replay();};
fillSheet(stops[0],0);
})();
